/*
 Problem: 1111. Maximum Nesting Depth of Two Valid Parentheses Strings
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 10.6 MB (19.54%)
 Tags: String, Stack, Bracket Sequences
*/
class Solution {
public:
    vector<int> maxDepthAfterSplit(string seq) {
        vector<int> answer;
        answer.reserve(seq.size());

        int depth = 0;

        for (char c : seq) {
            if (c == '(') {
                ++depth;
                answer.push_back(depth % 2);
            } else {
                answer.push_back(depth % 2);
                --depth;
            }
        }

        return answer;
    }
};
